"""Render the characterization report and dictionary from the profiling CSVs."""
import csv
import json
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs'/'artifacts'/ 'caracterizacion'


def read(name):
    with (OUT / name).open(newline='') as stream:
        return list(csv.DictReader(stream))


def md_table(headers, rows):
    escape = lambda v: str(v).replace('|', '\\|').replace('\n', ' ')
    lines = ['| ' + ' | '.join(headers) + ' |', '| ' + ' | '.join(['---']*len(headers)) + ' |']
    lines.extend('| ' + ' | '.join(escape(v) for v in row) + ' |' for row in rows)
    return '\n'.join(lines)


def render():
    summary = read('resumen_grupos.csv')
    variables = read('variables.csv')
    categories = read('categorias.csv')
    files = read('archivos.csv')
    texts = read('texto_libre.csv')
    links = read('vinculos_reservas_encuestas.csv')
    differences = read('consistencia_entre_fuentes.csv')
    temporal = read('cobertura_variables_periodo.csv')
    variants = read('variantes_categoricas.csv')
    base = {
        'ID': 'Identificador del evento de reserva. Único en cada grupo; todas las encuestas lo comparten con Reservas.',
        'Fecha inicio': 'Inicio programado del evento, interpretado a partir del encabezado y del formato Excel.',
        'Fecha fin': 'Fin programado del evento. No equivale a una salida real registrada.',
        'Fecha de llegada': 'Marca temporal de llegada según el encabezado; confirmar procedimiento de captura y excepciones.',
        'Fecha de devolución': 'Campo temporal sin valores en todos los archivos; su significado operativo debe confirmarse.',
        'Estado de la reserva': 'Estado del evento de reserva, con 12 etiquetas en la fuente principal. No confundir con Estado de la encuesta.',
        'Prioritaria': 'Indicador sí/no de prioridad de la reserva; confirmar regla de asignación.',
        'Categoría': 'Categoría de recurso o prestación, como Tutor Presencial; incluye identificadores históricos Deprecated.',
        'Tipo de horario': 'Modalidad o tipo de agenda: Normal, Express, Normal pico y otras modalidades históricas.',
        'Servicio': 'Servicio o curso asociado: IP, EDA y etiquetas históricas, entre otros.',
        'Código servicio': 'Código de servicio en Reservas; corresponde al campo Código del servicio en encuestas.',
        'Código del servicio': 'Código de servicio en encuestas; homologar el nombre con Código servicio sin modificar el original.',
        'Usuario': 'Nombre del usuario que reserva; no utilizar como clave única de persona.',
        'Correo usuario': 'Correo del usuario; conservar como atributo, sujeto a validación de identidad.',
        'Código usuario': 'Identificador de usuario exportado como texto. Sus 9.943 valores distintos en Reservas no demuestran 9.943 estudiantes únicos.',
        'Tipo de usuario': 'Clasificación del usuario en Bookeau; no corresponde al programa académico.',
        'Programa': 'Programa reportado para el usuario. Presenta variantes de escritura; no equivale a una lista homologada de programas.',
        'Prestador del servicio': 'Prestador o tutor asociado según el encabezado. Frecuentemente vacío en eventos sin atención; confirmar lógica de asignación.',
        'Estado': 'Estado de validez de la respuesta de encuesta: Válida o Inválida. No es el estado de asistencia.',
    }
    dictionary = []
    for variable in variables:
        name = variable['variable']
        is_text = variable['rol_inicial'] == 'texto libre'
        description = base.get(name, 'Respuesta de texto libre a la consigna del encabezado.' if is_text else 'Respuesta a la pregunta o afirmación del encabezado; dominio observado disponible en categorias.csv.')
        if name == 'Califique la ayuda que le dio su tutor':
            description = 'Calificación de la ayuda del tutor. Valores observados: 1 a 5; confirmar extremos y significado de la escala con la fuente.'
        available = [r['periodo'] for r in temporal if r['grupo']==variable['grupo'] and r['variable']==name and int(r['no_vacios'])]
        dictionary.append({'grupo':variable['grupo'],'variable':name,'descripcion_inicial':description,'rol':variable['rol_inicial'],'tipos_observados':variable['tipos_observados'],'faltantes':variable['faltantes'],'porcentaje_faltantes':variable['porcentaje_faltantes'],'valores_distintos':variable['valores_distintos'],'primer_periodo_con_valores':min(available) if available else '', 'ultimo_periodo_con_valores':max(available) if available else '', 'confirmacion_semantica':'ID y vínculos comprobados en los datos' if name=='ID' else 'Interpretación por encabezado; validar con responsable de la fuente'})
    with (OUT/'diccionario_variables.csv').open('w',newline='') as stream:
        writer=csv.DictWriter(stream,fieldnames=list(dictionary[0]))
        writer.writeheader(); writer.writerows(dictionary)
    dl = ['# Diccionario inicial de variables', '', 'Los nombres se conservan como vienen de Bookeau. Los significados operativos se infieren de los encabezados y del README de la fuente, salvo los vínculos de ID verificados. Confirmar captura, escalas y reglas con el responsable de CupiTaller.', '', 'El detalle completo está en `diccionario_variables.csv`; tipos, nulos y cardinalidad están en `variables.csv`. Los períodos de primera y última respuesta no prueban cuándo se creó una pregunta: pueden reflejar cambios del formulario, de etiquetas o del exportador.', '', '## Variables comunes', '', md_table(['Variable','Descripción inicial'],list(base.items())), '']
    for group in [s['grupo'] for s in summary if s['grupo']!='Reservas']:
        ds=[d for d in dictionary if d['grupo']==group and d['variable'] not in base]
        dl.extend(['## '+group, '', md_table(['Pregunta / variable','Tipo inicial','No vacíos','% faltantes','Primer período con valores'],[(d['variable'],d['rol'],int(next(v['no_vacios'] for v in variables if v['grupo']==group and v['variable']==d['variable'])),d['porcentaje_faltantes'],d['primer_periodo_con_valores']) for d in ds]),''])
    (OUT/'diccionario_variables.md').write_text('\n'.join(dl)+'\n')
    n=lambda value: f'{int(value):,}'
    meanings={'Reservas':'Un evento de reserva; incluye atención, cancelación, espera y otros estados.', 'Encuesta Express':'Una respuesta de satisfacción asociada a una reserva Express.', 'Encuesta Normal':'Una respuesta de satisfacción asociada a una reserva Normal.', 'Encuesta Reserva Express':'Una respuesta previa a la reserva Express: objetivo y aceptación de condiciones.', 'Encuesta Reserva Normal IP':'Una respuesta previa a la reserva Normal IP: objetivo y aceptación de condiciones.'}
    order=['Reservas','Encuesta Reserva Express','Encuesta Reserva Normal IP','Encuesta Express','Encuesta Normal']
    indexed={s['grupo']:s for s in summary}
    lines=['# Caracterización de datos · Bookeau', '', '## 1. Contexto y alcance', '', 'Las fuentes corresponden a reservas y encuestas de las tutorías de CupiTaller gestionadas con Bookeau, según el README del paquete. Se analizaron **todos los 114 archivos Excel y sus 114 hojas**, manteniendo intactos los originales. Hay cinco grupos de fuentes y **146.952 filas** en total, pero corresponden a **86.562 eventos de reserva distintos** y respuestas asociadas. Cada encuesta reutiliza el ID de una reserva; sumar las filas de las cinco fuentes sobrecontaría eventos.', '', 'La fecha programada de inicio va del **19 de agosto de 2016 al 22 de mayo de 2026**. Los archivos utilizan códigos de período de seis dígitos; no deben convertirse a fechas de mes usando sus dos últimos dígitos. El calendario académico y el significado de períodos terminados en 10, 19 y 20 requieren confirmación.', '', '## 2. Qué representa cada fuente', '', md_table(['Fuente','Archivos','Filas','Variables','Una fila representa'],[(g,indexed[g]['archivos'],n(indexed[g]['filas']),indexed[g]['variables'],meanings[g]) for g in order]), '', 'Reservas contiene 17 atributos; las cuatro encuestas repiten esos atributos (con una diferencia de nombre del código de servicio), agregan `Estado` de validez de encuesta y 4, 15 o 17 preguntas según el grupo. Dentro de cada grupo hay una sola variante de encabezados entre sus archivos; esto no demuestra que el cuestionario ni el significado de las etiquetas hayan sido estables históricamente.', '', 'El tamaño de Reservas está dentro del rango de 80.000–200.000 registros del enunciado, utilizando evento de reserva como unidad. Esa unidad debe mantenerse explícita al describir el volumen del proyecto.', '', '## 3. Información disponible', '', md_table(['Bloque','Información','Uso potencial'],[
    ('Evento y tiempo','ID, inicio/fin programados, llegada, estado y prioridad','Volumen, agenda, estados, duración programada y puntualidad con límites.'),
    ('Servicio','Categoría, tipo de horario, servicio y código','Segmentación de demanda por modalidad y servicio.'),
    ('Participantes','Usuario, correo, código, tipo, programa y prestador','Segmentación y recurrencia después de validar identidades y categorías.'),
    ('Encuesta previa','Objetivo declarado y aceptación de condiciones','Motivos de reserva y caracterización del uso esperado.'),
    ('Encuesta posterior','Calificación, comprensión, percepción del tutor, aprendizaje y uso de IA','Satisfacción y percepción; no demuestra efecto causal sobre aprendizaje.'),
    ('Texto libre','Comentarios sobre tutoría, curso, sugerencias y herramienta de IA','Material textual para siguientes entregas, tras revisar pertinencia y contenido.')]), '', 'Los nombres, tipos observados, significado inicial y completitud de cada campo están en [diccionario_variables.md](diccionario_variables.md). Los identificadores deben conservarse como identificadores, incluso si Excel los exporta numéricos; no son medidas para promediar.', '', 'En Reservas hay 9.943 códigos de usuario distintos, 9.932 correos distintos, 742 nombres de prestador no vacíos y 213 etiquetas de programa. Son cardinalidades de valores exportados, no conteos certificados de personas, tutores o programas homologados.', '', '## 4. Cobertura temporal', '', md_table(['Fuente','Primer inicio observado','Último inicio observado','Archivos sin registros'],[(g,indexed[g]['inicio_min'][:10],indexed[g]['inicio_max'][:10],', '.join(f['periodo'] for f in files if f['grupo']==g and f['filas']=='0') or 'Ninguno') for g in order]), '', 'Las encuestas previas tienen registros desde octubre de 2019 y no cubren todos los períodos de Reservas. Un archivo ausente o vacío no demuestra falta de demanda. La calificación numérica del tutor tiene respuestas desde 201819; preguntas sobre comprensión y uso de IA aparecen con valores en períodos diferentes según el grupo. Los períodos con respuesta se documentan en `cobertura_variables_periodo.csv`; validar formularios históricos antes de comparar series o interpretar esos períodos como fechas de introducción.', '', '## 5. Identificadores y relaciones', '', 'El campo `ID` es completo y único en cada grupo. Se encontraron **cero filas excedentes por ID repetido y cero duplicados exactos** dentro de cada fuente. El 100% de los registros de cada encuesta corresponde a una reserva existente, tanto por ID como por ID y período.', '', md_table(['Encuesta','Filas','ID con reserva','Sin reserva'],[(r['grupo_encuesta'],n(r['filas_con_id']),n(r['id_en_reservas']),r['filas_sin_id_en_reservas']) for r in links]), '', 'La relación observada es una reserva a cero o una respuesta en cada grupo de encuesta. Las respuestas previas y posteriores pueden pertenecer a la misma reserva. Conservarlas como registros asociados; no concatenarlas como reservas nuevas. La unicidad observada en esta extracción debe volver a comprobarse al recibir nuevos datos.', '', '```mermaid\nflowchart LR\n    R[Reservas: ID único] -->|ID: 0 o 1 respuesta| PE[Previa Express]\n    R -->|ID: 0 o 1 respuesta| PN[Previa Normal IP]\n    R -->|ID: 0 o 1 respuesta| SE[Satisfacción Express]\n    R -->|ID: 0 o 1 respuesta| SN[Satisfacción Normal]\n```', '', '## 6. Calidad y límites encontrados', '', '### Completitud', '', md_table(['Campo en Reservas','Faltantes','Porcentaje'],[(v['variable'],n(v['faltantes']),v['porcentaje_faltantes']+'%') for v in variables if v['grupo']=='Reservas' and int(v['faltantes'])]), '', '**Fecha de devolución está vacía en las cinco fuentes.** No se puede calcular duración efectiva ni tiempo real de salida. Inicio y fin programados son completos y dan duraciones de 20 a 120 minutos en Reservas, con mediana de 50 minutos. Las medianas en satisfacción son 30 minutos para Express y 55 para Normal; no suponer que toda reserva Normal equivale a 60 minutos.', '', 'Los faltantes de llegada o prestador dependen del estado del evento y no deben tratarse todos como errores. `estado_llegada.csv` muestra 8 reservas Finalizada sin llegada, 9 No asistió con llegada y pequeñas cantidades de cancelaciones con llegada; son casos para revisión operativa. Una marca de llegada no define por sí sola que la sesión se completó.', '', '### Categorías, unicidad y validez', '', 'Reservas contiene 12 estados, 11 categorías, 10 tipos de horario, 11 servicios y 6 tipos de usuario. Hay etiquetas `Deprecated` que requieren un catálogo histórico, y variantes de programa que difieren por mayúsculas, tildes o espacios. `variantes_categoricas.csv` identifica candidatos para homologar, sin aplicar cambios.', '', 'Las encuestas de satisfacción tienen 53 respuestas Express y 111 Normal marcadas `Inválida`; la encuesta previa Normal IP tiene 2. La previa Express no tiene respuestas marcadas inválidas. Confirmar el significado de esa etiqueta antes de excluir respuestas.', '', 'La calificación del tutor tiene 4.983 respuestas no vacías en Express y 11.326 en Normal; todas tienen valores enteros entre 1 y 5. Faltan 1.776 y 5.053 respuestas respectivamente. El dominio 1–5 se deriva de lo observado; confirmar el cuestionario y sus anclajes antes de interpretar promedios.', '', 'No se encontraron fechas fin anteriores al inicio ni inicios fuera del año del código de período. La coherencia llegada–devolución no es evaluable por ausencia total de devolución. Estas comprobaciones son parciales: no validan todas las reglas del negocio.', '', '### Consistencia entre fuentes', '', 'El nombre `Código servicio` en Reservas equivale al encabezado `Código del servicio` en encuestas para los pares comparados. Al vincular por ID y período, las fechas y códigos de servicio no muestran diferencias entre pares no vacíos. Sí hay diferencias en estado de reserva, código de usuario, programa, usuario y prestador.', '', md_table(['Encuesta','Diferencias de estado','Diferencias de código usuario','Diferencias de prestador'],[(g, next(r['diferencias'] for r in differences if r['grupo_encuesta']==g and r['variable']=='Estado de la reserva'), next(r['diferencias'] for r in differences if r['grupo_encuesta']==g and r['variable']=='Código usuario'), next(r['diferencias'] for r in differences if r['grupo_encuesta']==g and r['variable']=='Prestador del servicio')) for g in order if g!='Reservas']), '', 'Las diferencias no demuestran errores por sí solas: podrían deberse a actualizaciones o a variantes de representación. Definir fuente de referencia y regla de conciliación con el responsable antes de sobrescribir atributos.', '', '## 7. Datos de texto', '', md_table(['Fuente','Campo','Respuestas no vacías','Cobertura'],[(r['grupo'],r['variable'],n(r['respuestas_no_vacias']),r['porcentaje_cobertura']+'%') for r in texts]), '', 'Hay **17.987 respuestas no vacías** al comentario sobre tutor y tutoría entre Express y Normal. La longitud mediana es de 26 y 29 caracteres respectivamente. Tener texto no garantiza un comentario sustantivo: los conteos excluyen vacíos y espacios, pero no clasifican respuestas como “no aplica”, signos o frases genéricas. La pertinencia del corpus se debe evaluar antes del análisis textual.', '', '## 8. Qué podemos analizar y qué falta confirmar', '', '- Demanda: eventos por período, servicio y modalidad. Separar espera, cancelación y atención para no llamar tutorías atendidas a todas las reservas.\n- Asistencia: estados y marcas de llegada, una vez confirmadas las reglas del proceso.\n- Satisfacción: calificaciones y respuestas por modalidad y período, considerando validez, no respuesta y cambios históricos del cuestionario.\n- Motivos y texto: objetivos de reservas, comentarios de tutorías y observaciones sobre el curso.\n- No hay notas académicas ni medidas de aprendizaje objetivo, costos, ingresos o capacidad disponible explícita. Estos datos no permiten por sí solos medir impacto causal en aprendizaje, rentabilidad o utilización de capacidad.', '', 'Antes del modelo y los indicadores, confirmar: significado de los estados (incluidos Realizada y Finalizada), momento de captura de llegada, códigos de período, catálogos Deprecated, identidad de usuario y prestador, formularios y escalas históricos, y motivo de invalidez de encuestas.', '', '## 9. Método y reproducción', '', 'Se leyeron directamente los XML internos de todos los XLSX usando la biblioteca estándar de Python. Las celdas se alinean por coordenada Excel; los huecos no desplazan columnas. Las fechas se decodifican usando estilos y sistema de fechas del libro. Se considera faltante una celda ausente, vacía o con espacios; textos como “No aplica” no se convierten automáticamente en nulos.', '', 'Los duplicados exactos se evalúan dentro de cada grupo sobre todas las columnas de origen, sin añadir período ni ruta al contenido. Las diferencias entre fuentes se comparan solo en pares no vacíos con una reserva inequívoca en el mismo período; se tolera hasta un segundo de diferencia en fechas por representación Excel.', '', 'Ejecutar desde la raíz del proyecto:', '', '```sh\npython3 src/caracterizar_bookeau.py\npython3 src/documentar_caracterizacion.py\n```', '', 'Los scripts regeneran tablas y documentos de caracterización. No limpian ni transforman los originales. El cuaderno `notebooks/01_caracterizacion_bookeau.ipynb` permite consultar los resultados y volver a generarlos.', '', 'Los resultados describen esta extracción completa, no la calidad garantizada de futuras cargas ni un diccionario confirmado por el dueño de los datos.']
    (OUT/'caracterizacion_bookeau.md').write_text('\n'.join(lines)+'\n')
    print('Report and dictionary generated:', OUT)


if __name__ == '__main__':
    render()
